# Modify this to change how the CLI connects to the MCP server.
CLIENT_SPEC = StdioTransport(command=sys.executable, args=['-m', 'astrophotoflow.interfaces.mcp.server'], env={**({'ASTROPHOTOFLOW_CONFIG': os.environ['ASTROPHOTOFLOW_CONFIG']} if 'ASTROPHOTOFLOW_CONFIG' in os.environ else {}), 'PYTHONUTF8': '1'})

app = cyclopts.App(name="astrophotoflow", help="CLI for AstroPhotoFlow MCP server")
call_tool_app = cyclopts.App(name="call-tool", help="Call a tool on the server")
app.command(call_tool_app)

console = Console()


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _print_tool_result(result):
    if result.is_error:
        for block in result.content:
            if isinstance(block, mcp_types.TextContent):
                console.print(f"[bold red]Error:[/bold red] {block.text}")
            else:
                console.print(f"[bold red]Error:[/bold red] {block}")
        sys.exit(1)

    if result.structured_content is not None:
        console.print_json(json.dumps(result.structured_content))
        return

    for block in result.content:
        if isinstance(block, mcp_types.TextContent):
            console.print(block.text)
        elif isinstance(block, mcp_types.ImageContent):
            size = len(block.data) * 3 // 4
            console.print(f"[dim][Image: {block.mime_type}, ~{size} bytes][/dim]")
        elif isinstance(block, mcp_types.AudioContent):
            size = len(block.data) * 3 // 4
            console.print(f"[dim][Audio: {block.mime_type}, ~{size} bytes][/dim]")


_REQUIRED_NULLABLE_ARGUMENTS = {}


async def _call_tool(tool_name: str, arguments: dict) -> None:
    required_nullable = _REQUIRED_NULLABLE_ARGUMENTS.get(tool_name, ())
    filtered = {k: v for k, v in arguments.items() if v is not None or k in required_nullable}
    async with Client(CLIENT_SPEC) as client:
        result = await client.call_tool(tool_name, filtered, raise_on_error=False)
        _print_tool_result(result)
        if result.is_error:
            sys.exit(1)


