    '''Read-only calibration check of exact scanned files, proposed metadata/equipment and fixed targets BEFORE import. Returns conflicts and unknowns for Agent questions; never registers files or approves unknowns. Explain suggestions and obtain user confirmation before import; unknown values may remain unknown. 校准 导入前 扫描 检查 未知 提问'''
    # Parse JSON parameters
    files = json.loads(files) if isinstance(files, str) else files
    defaults = json.loads(defaults) if isinstance(defaults, str) else defaults
    calibration = json.loads(calibration) if isinstance(calibration, str) else calibration
    destination = json.loads(destination) if isinstance(destination, str) else destination

    await _call_tool('data_calibration_check_import', {'scan_id': scan_id, 'files': files, 'defaults': defaults, 'calibration': calibration, 'destination': destination, 'limit': limit, 'offset': offset})


